func commandName(comp, cmd uint16) string {
	if n, ok := commandNames[uint32(comp)<<16|uint32(cmd)]; ok {
		return componentNames[comp] + "." + n
	}
	return fmt.Sprintf("%s.%#x", componentName(comp), cmd)
}

func notificationName(comp, cmd uint16) string {
	if n, ok := notificationNames[uint32(comp)<<16|uint32(cmd)]; ok {
		return componentNames[comp] + "." + n
	}
	return fmt.Sprintf("%s.ntf%#x", componentName(comp), cmd)
}

func componentName(comp uint16) string {
	if n, ok := componentNames[comp]; ok {
		return n
	}
	return fmt.Sprintf("comp%#x", comp)
}
